class Solution {
    public ListNode reverseEvenLengthGroups(ListNode head) {
        ListNode prevGroupTail = null;
        ListNode curr = head;
        int groupLen = 1;

        while (curr != null) {
            int count = 0;
            ListNode temp = curr;
            while (temp != null && count < groupLen) {
                count++;
                temp = temp.next;
            }

            if (count % 2 == 0) {
                ListNode revPrev = null;
                ListNode revCurr = curr;
                for (int i = 0; i < count; i++) {
                    ListNode nxt = revCurr.next;
                    revCurr.next = revPrev;
                    revPrev = revCurr;
                    revCurr = nxt;
                }
                if (prevGroupTail != null) prevGroupTail.next = revPrev;
                curr.next = revCurr;
                prevGroupTail = curr;
                curr = revCurr;
            } else {
                for (int i = 0; i < count; i++) {
                    prevGroupTail = curr;
                    curr = curr.next;
                }
            }
            groupLen++;
        }
        return head;
    }
};

